EXPLAIN SELECT * FROM orders;

EXPLAIN (TYPE DISTRIBUTED) SELECT * FROM orders;

EXPLAIN (FORMAT JSON, TYPE IO) SELECT * FROM orders;

EXPLAIN (FORMAT GRAPHVIZ, TYPE LOGICAL) SELECT * FROM orders;

EXPLAIN (TYPE VALIDATE) SELECT * FROM orders;

EXPLAIN ANALYZE SELECT * FROM orders;

EXPLAIN ANALYZE VERBOSE SELECT * FROM orders;

EXPLAIN ANALYZE INSERT INTO orders SELECT * FROM staging_orders;

EXPLAIN MERGE INTO target USING source ON target.id = source.id
WHEN MATCHED THEN DELETE;

EXPLAIN (TYPE IO) MERGE INTO target USING source ON target.id = source.id
WHEN MATCHED THEN DELETE;

EXPLAIN ANALYZE MERGE INTO target USING source ON target.id = source.id
WHEN MATCHED THEN DELETE;
